#!/usr/bin/env node
// Zero-dependency bundler: compiles modular ES source files in js/*.js into
// a single classic script js/app.bundle.js so index.html works BOTH via HTTP/HTTPS
// AND via direct double-click (file://) without browser ES-module CORS blocking!

import fs from 'node:fs';
import path from 'node:path';
import { fileURLToPath } from 'node:url';

const __dirname = path.dirname(fileURLToPath(import.meta.url));
const jsDir = path.join(__dirname, 'js');

// Topological dependency order
const MODULES = [
  'utils.js',
  'qr.js',
  'parser.js',
  'chords.js',
  'storage.js',
  'renderer.js',
  'remote.js',
  'stage.js',
  'editor.js',
  'library.js',
  'main.js'
];

const modVar = file => '__m_' + file.replace(/\.js$/, '').replace(/[^a-z0-9_]/gi, '_');

const chunks = [
  '// Auto-generated by build-bundle.mjs from js/*.js – do not edit directly.',
  '// Classic IIFE bundle so ChordPro Studio works over http(s):// AND file:// (double-click).',
  '(function () {',
  '"use strict";'
];

for (const file of MODULES) {
  let code = fs.readFileSync(path.join(jsDir, file), 'utf8');
  const exportsList = [];

  // Replace relative ES imports with destructuring from previously bundled module objects
  code = code.replace(
    /import\s*\{([^}]+)\}\s*from\s*['"]\.\/([^'"]+)['"];?/g,
    (_, names, targetFile) => {
      const cleaned = names
        .split(',')
        .map(s => s.trim())
        .filter(Boolean)
        .map(s => s.replace(/\s+as\s+/, ': '))
        .join(', ');
      return `const { ${cleaned} } = ${modVar(targetFile)};`;
    }
  );

  // Transform `export function name(`
  code = code.replace(/^export\s+(async\s+)?function\s+([a-zA-Z0-9_$]+)/gm, (_, asyncKw, name) => {
    exportsList.push({ name, live: false });
    return `${asyncKw || ''}function ${name}`;
  });

  // Transform `export const name =`
  code = code.replace(/^export\s+const\s+([a-zA-Z0-9_$]+)/gm, (_, name) => {
    exportsList.push({ name, live: false });
    return `const ${name}`;
  });

  // Transform `export let name =` (use live getter so reassignments propagate!)
  code = code.replace(/^export\s+let\s+([a-zA-Z0-9_$]+)/gm, (_, name) => {
    exportsList.push({ name, live: true });
    return `let ${name}`;
  });

  // Transform `export class name`
  code = code.replace(/^export\s+class\s+([a-zA-Z0-9_$]+)/gm, (_, name) => {
    exportsList.push({ name, live: false });
    return `class ${name}`;
  });

  const returnProps = exportsList
    .map(e => (e.live ? `get ${e.name}() { return ${e.name}; }` : e.name))
    .join(', ');

  chunks.push(`\n// === ${file} ===`);
  chunks.push(`const ${modVar(file)} = (() => {\n${code}\nreturn { ${returnProps} };\n})();`);
}

chunks.push('\n})();\n');

const outPath = path.join(jsDir, 'app.bundle.js');
fs.writeFileSync(outPath, chunks.join('\n'), 'utf8');
console.log(`Built ${outPath} (${Math.round(fs.statSync(outPath).size / 1024)} KB)`);
